import type { HTMLAttributes, ReactNode } from "react";
import "./LayeredBadge.css";

export type LayeredBadgeTone =
  | "neutral"
  | "copper"
  | "green"
  | "gold"
  | "signal-red";

export type LayeredBadgeSize = "small" | "medium";

export interface LayeredBadgeProps extends HTMLAttributes<HTMLSpanElement> {
  children: ReactNode;
  tone?: LayeredBadgeTone;
  badgeSize?: LayeredBadgeSize;
}

export function LayeredBadge({
  children,
  tone = "neutral",
  badgeSize = "small",
  className = "",
  ...props
}: LayeredBadgeProps) {
  return (
    <span
      {...props}
      className={["layered-badge", className].filter(Boolean).join(" ")}
      data-tone={tone}
      data-size={badgeSize}
    >
      {children}
    </span>
  );
}

.layered-badge {
    --badge-tone-light: var(--tone-neutral-light);
    --badge-tone-dark: var(--tone-neutral-dark);
    --badge-tone-text: var(--color-text);
    --badge-font-size: 0.625rem;
    --badge-padding-block: 2px;
    --badge-padding-inline: 7px;

    display: inline-flex;
    align-items: center;
    box-sizing: border-box;
    width: max-content;
    max-width: 100%;
    min-height: 20px;
    padding: var(--badge-padding-block) var(--badge-padding-inline);
    overflow: hidden;
    border: 1px solid color-mix(in srgb, var(--badge-tone-light) 38%, var(--control-trench));
    border-radius: 4px;
    background:
        linear-gradient(180deg,
            color-mix(in srgb, var(--badge-tone-light) 12%, var(--input-surface-bg-top)) 0%,
            color-mix(in srgb, var(--badge-tone-dark) 18%, var(--input-surface-bg-bottom)) 100%);
    color: var(--badge-tone-text);
    box-shadow:
        inset 0 1px color-mix(in srgb, var(--badge-tone-light) 18%, transparent),
        inset 0 -1px rgb(0 0 0 / 28%),
        0 1px 2px rgb(0 0 0 / 24%);
    font-size: var(--badge-font-size);
    font-weight: 750;
    line-height: 1.2;
    letter-spacing: 0.085em;
    text-overflow: ellipsis;
    text-transform: uppercase;
    vertical-align: middle;
    white-space: nowrap;
}

.layered-badge[data-size="medium"] {
    --badge-font-size: 0.7rem;
    --badge-padding-block: 3px;
    --badge-padding-inline: 9px;

    min-height: 24px;
}

.layered-badge[data-tone="copper"] {
    --badge-tone-light: var(--tone-copper-light);
    --badge-tone-dark: var(--tone-copper-dark);
    --badge-tone-text: color-mix(in srgb, var(--tone-copper-light) 82%, var(--color-text));
}

.layered-badge[data-tone="green"] {
    --badge-tone-light: var(--tone-green-light);
    --badge-tone-dark: var(--tone-green-dark);
    --badge-tone-text: color-mix(in srgb, var(--tone-green-light) 82%, var(--color-text));
}

.layered-badge[data-tone="gold"] {
    --badge-tone-light: var(--tone-gold-light);
    --badge-tone-dark: var(--tone-gold-dark);
    --badge-tone-text: color-mix(in srgb, var(--tone-gold-light) 82%, var(--color-text));
}

.layered-badge[data-tone="signal-red"] {
    --badge-tone-light: var(--palette-red-400);
    --badge-tone-dark: var(--palette-red-950);
    --badge-tone-text: var(--palette-red-100);

    border-color: color-mix(in srgb, var(--palette-red-500) 62%, var(--control-trench));
    background:
        linear-gradient(180deg,
            color-mix(in srgb, var(--palette-red-700) 30%, var(--input-surface-bg-top)) 0%,
            color-mix(in srgb, var(--palette-red-950) 48%, var(--input-surface-bg-bottom)) 100%);
    box-shadow:
        inset 0 1px rgb(255 255 255 / 6%),
        inset 0 -1px rgb(0 0 0 / 38%),
        0 1px 2px rgb(0 0 0 / 28%);
}

@media (forced-colors: active) {
    .layered-badge {
        forced-color-adjust: auto;
        border-color: CanvasText;
        background: Canvas;
        color: CanvasText;
        box-shadow: none;
    }
}
